using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Windows.Forms;

public sealed partial class CompanionWindow {
    sealed class TelemetryFileChoice {public string Path;public override string ToString(){return System.IO.Path.GetFileNameWithoutExtension(Path);}}
    void CreateTelemetryCompare(TableLayoutPanel stack){
        var panel=new TableLayoutPanel{Dock=DockStyle.Top,AutoSize=true,ColumnCount=1,BackColor=GtcTheme.Surface,Padding=new Padding(P(14)),Margin=new Padding(0,0,0,P(12))};panel.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));stack.Controls.Add(panel);
        var heading=TextLabel("COMPARAR TELEMETRIA",11,true);heading.ForeColor=GtcTheme.Muted;heading.Margin=new Padding(0,0,0,P(8));panel.Controls.Add(heading);
        var info=TextLabel("Escolhe duas voltas completas gravadas pelo Companion, na mesma pista.",11);info.ForeColor=GtcTheme.Muted;info.MaximumSize=new Size(P(460),0);panel.Controls.Add(info);
        Func<string,ComboBox> darkCombo=label=>{var combo=new ComboBox{Dock=DockStyle.Top,DropDownStyle=ComboBoxStyle.DropDownList,DrawMode=DrawMode.OwnerDrawFixed,ItemHeight=P(24),BackColor=GtcTheme.Input,ForeColor=GtcTheme.Text,FlatStyle=FlatStyle.Flat,Font=F(11),AccessibleName=label};combo.DrawItem+=(s,e)=>{if(e.Index<0)return;using(var brush=new SolidBrush((e.State&DrawItemState.Selected)!=0?GtcTheme.AccentSurface:GtcTheme.Input))e.Graphics.FillRectangle(brush,e.Bounds);TextRenderer.DrawText(e.Graphics,AppLanguage.T(combo.Items[e.Index].ToString()),combo.Font,e.Bounds,GtcTheme.Text,TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);};return combo;};
        Func<string,ComboBox> selector=label=>{var title=TextLabel(label,11,true);title.Margin=new Padding(0,P(10),0,P(4));panel.Controls.Add(title);var combo=darkCombo(label);panel.Controls.Add(combo);return combo;};
        var first=selector("Volta A · referência");var second=selector("Volta B · comparação");
        var buttons=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,WrapContents=true,Margin=new Padding(0,P(10),0,P(8))};panel.Controls.Add(buttons);var refresh=Button("Atualizar lista",140);var importA=Button("Abrir A…",100);var importB=Button("Abrir B…",100);var folder=Button("Replays guardados",150);buttons.Controls.Add(refresh);buttons.Controls.Add(importA);buttons.Controls.Add(importB);buttons.Controls.Add(folder);folder.Click+=(s,e)=>{string path=Path.Combine(CompanionStore.Root,"replays");Directory.CreateDirectory(path);System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(path){UseShellExecute=true});};
        string directory=Path.Combine(CompanionStore.Root,"telemetry","laps");
        Action reload=()=>{string pa=(first.SelectedItem as TelemetryFileChoice)==null?null:((TelemetryFileChoice)first.SelectedItem).Path,pb=(second.SelectedItem as TelemetryFileChoice)==null?null:((TelemetryFileChoice)second.SelectedItem).Path;first.Items.Clear();second.Items.Clear();if(Directory.Exists(directory))foreach(var file in Directory.GetFiles(directory,"*.csv",SearchOption.AllDirectories).OrderByDescending(File.GetLastWriteTimeUtc).Take(1000)){first.Items.Add(new TelemetryFileChoice{Path=file});second.Items.Add(new TelemetryFileChoice{Path=file});}Func<ComboBox,string,int> find=(combo,path)=>{for(int i=0;i<combo.Items.Count;i++)if(string.Equals(((TelemetryFileChoice)combo.Items[i]).Path,path,StringComparison.OrdinalIgnoreCase))return i;return -1;};first.SelectedIndex=find(first,pa);second.SelectedIndex=find(second,pb);};
        Action<ComboBox> pick=combo=>{using(var dialog=new OpenFileDialog{Title="Selecionar volta de telemetria",Filter="Telemetria CSV (*.csv)|*.csv",InitialDirectory=Directory.Exists(directory)?directory:Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),CheckFileExists=true})if(dialog.ShowDialog(this)==DialogResult.OK){combo.Items.Add(new TelemetryFileChoice{Path=dialog.FileName});combo.SelectedIndex=combo.Items.Count-1;}};refresh.Click+=(s,e)=>reload();importA.Click+=(s,e)=>pick(first);importB.Click+=(s,e)=>pick(second);
        var status=TextLabel("Escolhe duas voltas para começar.",11);status.ForeColor=GtcTheme.Muted;status.MaximumSize=new Size(P(470),0);status.Margin=new Padding(0,P(8),0,P(8));panel.Controls.Add(status);
        var metric=darkCombo("Canal de telemetria");metric.Items.AddRange(new object[]{"Acelerador","Travão","Direção"});metric.SelectedIndex=0;panel.Controls.Add(metric);
        var values=TextLabel("",11);values.ForeColor=GtcTheme.Text;values.MaximumSize=new Size(P(470),0);values.Margin=new Padding(0,P(8),0,P(4));panel.Controls.Add(values);
        var slider=new GtcSettingsSlider{Minimum=0,Maximum=1000,Height=P(30),Dock=DockStyle.Top,BackColor=GtcTheme.Surface,AccessibleName="Posição ao longo da volta"};panel.Controls.Add(slider);
        var chart=new TelemetryCompareChart{Dock=DockStyle.Top,Height=P(500),Margin=new Padding(0,P(4),0,P(4))};panel.Controls.Add(chart);
        var foot=TextLabel("Laranja: A · Azul: B. Valores dos comandos brutos. O alinhamento usa a distância percorrida normalizada e é aproximado; trajetórias diferentes podem afetar o diferencial. A validade da volta não é determinada pelo CSV.",10);foot.ForeColor=GtcTheme.Muted;foot.MaximumSize=new Size(P(470),0);panel.Controls.Add(foot);
        Action updateValues=()=>{chart.Progress=slider.Value/1000d;chart.Metric=metric.SelectedIndex;chart.Invalidate();string problem=TelemetryLap.Problem(chart.First,chart.Second);if(problem!=null){values.Text="";return;}var a=chart.First.At(chart.Progress);var b=chart.Second.At(chart.Progress);Func<TelemetryPoint,double> val=p=>metric.SelectedIndex==0?p.Throttle:metric.SelectedIndex==1?p.Brake:p.Steering;double delta=b.Time-a.Time;values.Text=chart.First.Driver+" "+(val(a)*100).ToString("0")+"%  ·  "+chart.Second.Driver+" "+(val(b)*100).ToString("0")+"%  ·  B − A "+(delta>=0?"+":"")+delta.ToString("0.000")+" s";};
        Action load=()=>{chart.First=null;chart.Second=null;try{var a=first.SelectedItem as TelemetryFileChoice;var b=second.SelectedItem as TelemetryFileChoice;if(a!=null)chart.First=TelemetryLap.Load(a.Path);if(b!=null)chart.Second=TelemetryLap.Load(b.Path);string problem=TelemetryLap.Problem(chart.First,chart.Second);status.Text=problem??(chart.First.Driver+" · "+chart.Second.Driver+" · "+chart.First.Track+(string.Equals(chart.First.Car,chart.Second.Car,StringComparison.OrdinalIgnoreCase)?"":" · carros diferentes")+(chart.First.HasGaps||chart.Second.HasGaps?" · pequenas falhas de amostragem":""));status.ForeColor=problem==null?GtcTheme.Text:GtcTheme.Muted;}catch(Exception ex){status.Text="Não foi possível ler a volta: "+ex.Message;status.ForeColor=GtcTheme.Muted;}updateValues();};
        first.SelectedIndexChanged+=(s,e)=>load();second.SelectedIndexChanged+=(s,e)=>load();metric.SelectedIndexChanged+=(s,e)=>updateValues();slider.ValueChanged+=(s,e)=>updateValues();chart.ProgressChanged+=p=>slider.Value=(int)Math.Round(p*1000);reload();
    }
}
